package com.fireplatform;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fireplatform.shared.*;
import com.fireplatform.siminventory.*;
import java.math.*;
import java.sql.ResultSet;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import static com.fireplatform.siminventory.SimInventoryModels.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class SimInventoryProjectionTest {
    static final String CARD="123e4567-e89b-12d3-a456-426614174000",CHANGE="223e4567-e89b-12d3-a456-426614174000",TENANT="tenant-a",TIME="2026-01-02T03:04:05.123456Z";
    final ObjectMapper json=new ObjectMapper().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).enable(DeserializationFeature.USE_BIG_INTEGER_FOR_INTS).enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
    State state(){return new State(CARD,TENANT,"AVAILABLE","",1,TIME);}
    ObjectNode node(){return json.valueToTree(state());}
    void bad(org.assertj.core.api.ThrowableAssert.ThrowingCallable work){assertThatThrownBy(work).isInstanceOfSatisfying(ApiError.class,e->{assertThat(e.status).isEqualTo(503);assertThat(e.code).isEqualTo("SIM_INVENTORY_READ_UNCONFIRMED");assertThat(e.getMessage()).doesNotContain("SECRET");});}
    ResultSet change(long revision,String operation,String from,String to,String issued,String reason)throws Exception{var rs=mock(ResultSet.class);Map<String,String> fields=Map.of("change_id",CHANGE,"card_id",CARD,"tenant_id",TENANT,"operation",operation,"from_status",from,"to_status",to,"issued_to",issued,"reason",reason);when(rs.getString(anyString())).thenAnswer(call->fields.get(call.getArgument(0,String.class)));when(rs.getObject("revision")).thenReturn(revision);when(rs.getObject("recorded_at",OffsetDateTime.class)).thenReturn(OffsetDateTime.parse(TIME));return rs;}
    @Test void stateHistoryAndBothPagesHaveExactSixTenAndFiveKeys(){assertThat(node().size()).isEqualTo(6);var change=new Change(CHANGE,CARD,TENANT,1,"RECEIVE","UNREGISTERED","AVAILABLE","","",TIME);JsonNode history=json.valueToTree(change);assertThat(history.size()).isEqualTo(10);assertThat(history.toString()).doesNotContain("actor","username","changed","device_id","iccid");assertThat(json.valueToTree(new HistoryPage(List.of(change),1,1,20,1)).size()).isEqualTo(5);assertThat(json.valueToTree(new StatePage(List.of(state()),1,1,20,1)).size()).isEqualTo(5);}
    @Test void virtualZeroIsExactlyUnregisteredEmptyAndUntimed(){var empty=SimInventoryProjection.empty(TENANT,CARD);assertThat(empty.status()).isEqualTo("UNREGISTERED");assertThat(empty.revision()).isZero();assertThat(empty.issuedTo()).isEmpty();assertThat(empty.recordedAt()).isNull();bad(()->SimInventoryProjection.valid(new State(CARD,TENANT,"AVAILABLE","",0,null),TENANT,CARD));bad(()->SimInventoryProjection.valid(new State(CARD,TENANT,"UNREGISTERED","recipient",0,null),TENANT,CARD));bad(()->SimInventoryProjection.valid(new State(CARD,TENANT,"UNREGISTERED","",0,TIME),TENANT,CARD));}
    @Test void registeredStateRecipientAndTimestampCombinationsAreStrict(){for(String status:List.of("AVAILABLE","SCRAPPED")){assertThat(SimInventoryProjection.valid(new State(CARD,TENANT,status,"",1,TIME),TENANT,CARD).status()).isEqualTo(status);bad(()->SimInventoryProjection.valid(new State(CARD,TENANT,status,"recipient",1,TIME),TENANT,CARD));}assertThat(SimInventoryProjection.valid(new State(CARD,TENANT,"ISSUED","Recipient",1,TIME),TENANT,CARD).issuedTo()).isEqualTo("Recipient");for(String issued:Arrays.asList(null,""," recipient ","a\u0000b","\ud800"))bad(()->SimInventoryProjection.valid(new State(CARD,TENANT,"ISSUED",issued,1,TIME),TENANT,CARD));bad(()->SimInventoryProjection.valid(new State(CARD,TENANT,"UNREGISTERED","",1,TIME),TENANT,CARD));bad(()->SimInventoryProjection.valid(new State(CARD,TENANT,"AVAILABLE","",1,null),TENANT,CARD));}
    @Test void completeRegisteredAndVirtualStatesRoundTripStrictly()throws Exception{for(State value:List.of(state(),new State(CARD,TENANT,"ISSUED","Recipient",2,TIME),new State(CARD,TENANT,"SCRAPPED","",3,TIME),SimInventoryProjection.empty(TENANT,CARD)))assertThat(json.readValue(json.writeValueAsBytes(value),State.class)).isEqualTo(value);}
    @Test void allSixKeysAreMandatoryAndExtraChangedCardAndActorFieldsFail(){for(String key:SimInventoryProjection.STATE_COLUMNS.split(",")){var n=node();n.remove(key);bad(()->SimInventoryProjection.stored(n));}for(String key:List.of("changed","actor_user_id","iccid","device_id","reason")){var n=node();n.put(key,"SECRET");bad(()->SimInventoryProjection.stored(n));}}
    @Test void allStringFieldsAndNumbersRejectCoercionOrUnexpectedNull(){for(String key:SimInventoryProjection.STATE_COLUMNS.split(","))if(!key.equals("revision")){var n=node();n.put(key,1);bad(()->SimInventoryProjection.stored(n));}for(String key:List.of("card_id","tenant_id","status","issued_to","revision")){var n=node();n.putNull(key);bad(()->SimInventoryProjection.stored(n));}}
    @Test void rawCachedNegativeZeroExponentFractionStringAndUnsafeNumbersFail()throws Exception{String valid=json.writeValueAsString(SimInventoryProjection.empty(TENANT,CARD));for(String raw:List.of("-0","0.0","0e0","\"0\"","9007199254740992","-1"))assertThatThrownBy(()->json.readValue(valid.replace("\"revision\":0","\"revision\":"+raw),State.class)).isInstanceOf(Exception.class);}
    @Test void cachedNullMalformedDuplicateAndTrailingAreFailuresNotMisses()throws Exception{String valid=json.writeValueAsString(state());List<String> variants=List.of("null","[]","{",valid+" {}",valid.replace("\"revision\":1","\"revision\":1,\"revision\":1"),valid.substring(0,valid.length()-1)+",\"issued_to\":\"duplicate\"}");for(String raw:variants)assertThatThrownBy(()->json.readValue(raw,State.class)).isInstanceOf(Exception.class);}
    @Test void wrongTenantResourceAndNoncanonicalUuidNeverExposeAValidReceipt(){bad(()->SimInventoryProjection.valid(state(),"tenant-b",CARD));bad(()->SimInventoryProjection.valid(state(),TENANT,CHANGE));for(String id:List.of(CARD.toUpperCase(Locale.ROOT),"not-uuid"," "+CARD)){var n=node();n.put("card_id",id);bad(()->SimInventoryProjection.stored(n));}}
    @Test void databaseNumbersNeverTruncateOrDefaultNull(){for(Object raw:Arrays.asList(null,-1L,SimInventoryInputs.MAX_SAFE+1,new BigDecimal("0.01"),0.0,"1",BigInteger.valueOf(Long.MAX_VALUE).add(BigInteger.ONE)))bad(()->SimInventoryProjection.number(raw));assertThat(SimInventoryProjection.number(BigInteger.valueOf(SimInventoryInputs.MAX_SAFE))).isEqualTo(SimInventoryInputs.MAX_SAFE);}
    @Test void timestampsAreRealFixedSixUtcMicroseconds(){for(String time:List.of("2026-01-02T03:04:05Z","2026-01-02T03:04:05.1Z","2026-01-02T03:04:05.123456+00:00","0000-01-01T00:00:00.000000Z","2026-01-02T24:00:00.000000Z")){var n=node();n.put("recorded_at",time);bad(()->SimInventoryProjection.stored(n));}bad(()->SimInventoryProjection.instant(OffsetDateTime.parse("2026-01-02T03:04:05.123456789Z")));bad(()->SimInventoryProjection.instant(OffsetDateTime.of(9999,12,31,23,59,59,0,ZoneOffset.ofHours(-1))));}
    @Test void historyFirstRevisionIsExactlyUnregisteredAndCurrentLastStateMatches()throws Exception{assertThat(SimInventoryProjection.change(change(1,"RECEIVE","UNREGISTERED","AVAILABLE","",""),state()).revision()).isEqualTo(1);bad(()->SimInventoryProjection.change(change(1,"RECEIVE","AVAILABLE","AVAILABLE","",""),state()));bad(()->SimInventoryProjection.change(change(2,"RECEIVE","UNREGISTERED","AVAILABLE","",""),new State(CARD,TENANT,"AVAILABLE","",2,TIME)));bad(()->SimInventoryProjection.change(change(1,"ISSUE","UNREGISTERED","ISSUED","Recipient",""),state()));}
    @Test void historyScrapCorrectionAndRecipientEvidenceRulesAreChecked()throws Exception{var current=new State(CARD,TENANT,"AVAILABLE","",2,TIME);assertThat(SimInventoryProjection.change(change(2,"CORRECT","SCRAPPED","AVAILABLE",""," evidence "),current).reason()).isEqualTo(" evidence ");bad(()->SimInventoryProjection.change(change(2,"CORRECT","SCRAPPED","AVAILABLE",""," \t "),current));bad(()->SimInventoryProjection.change(change(2,"RECOVER","SCRAPPED","AVAILABLE","",""),current));bad(()->SimInventoryProjection.change(change(2,"CORRECT","AVAILABLE","AVAILABLE","","evidence"),current));bad(()->SimInventoryProjection.change(change(2,"RECEIVE","AVAILABLE","AVAILABLE","recipient",""),current));}
    @Test void collectionAndHistoryBothRejectCorruptDefaultEvenWithExplicitSize(){for(long value:new long[]{0,4,101,Long.MAX_VALUE})for(Integer requested:Arrays.asList(null,1)){var jdbc=mock(JdbcTemplate.class);var sizes=mock(PageSizePolicy.class);when(sizes.defaultPageSize()).thenReturn(value);var queries=new SimInventoryQueries(jdbc,sizes,mock(TransactionRequirements.class));bad(()->queries.list(TENANT,1,requested,null));bad(()->queries.history(TENANT,CARD,1,requested));assertThat(mockingDetails(jdbc).getInvocations()).isEmpty();}}
    @Test void explicitProjectionColumnsExcludeActorDirectoriesAndUnrelatedMetadata(){assertThat(SimInventoryProjection.STATE_COLUMNS.split(",")).hasSize(6);assertThat(SimInventoryProjection.CHANGE_COLUMNS.split(",")).hasSize(10);assertThat(SimInventoryProjection.CHANGE_COLUMNS).doesNotContain("actor","username","device_name","*","iccid","password");}
}
